import{_ as n,C as d,o as r,c as s,j as t,a as o,E as l,a5 as h}from"./chunks/framework.DtspaGiy.js";const w=JSON.parse('{"title":"Find and replace","description":"","frontmatter":{},"headers":[],"relativePath":"guide/find.md","filePath":"guide/find.md"}'),i={name:"guide/find.md"};function c(p,e,m,u,g,f){const a=d("Shot");return r(),s("div",null,[e[0]||(e[0]=t("h1",{id:"find-and-replace",tabindex:"-1"},[o("Find and replace "),t("a",{class:"header-anchor",href:"#find-and-replace","aria-label":'Permalink to "Find and replace"'},"​")],-1)),e[1]||(e[1]=t("p",null,[t("code",null,"Mod"),o(),t("code",null,"F"),o(" opens a small panel at the top right of your pages. Type what you're looking for: Blank highlights every match on the pages and shows where you are, like "),t("em",null,"3 of 12"),o(". The panel stays open while you write, so you can look, change something in the text and look on.")],-1)),l(a,{src:"find.gif",alt:"Mod F opens the find panel; typing chrome highlights both matches and says 1 of 2; Enter goes to the next; Replace all with color replaces both"}),e[2]||(e[2]=h('<h2 id="step" tabindex="-1">Go through the matches <a class="header-anchor" href="#step" aria-label="Permalink to &quot;Go through the matches {#step}&quot;">​</a></h2><ul><li><code>Enter</code> in the find field goes to the next match, <code>Shift</code> <code>Enter</code> to the previous one. The arrows below the fields do the same.</li><li><code>F3</code> and <code>Shift</code> <code>F3</code> work too while the panel is open, wherever you are but in a dialog or a menu.</li><li>The pages scroll to show the match you&#39;re at, which is highlighted more strongly than the others.</li></ul><p>If you selected a word or a few words before pressing <code>Mod</code> <code>F</code>, Blank looks for them right away. Otherwise the field shows what you looked for last in that document, selected, so you can type over it. Each tab remembers its own search.</p><p><code>Esc</code> in the panel closes it and selects the match you were at, so you can go on typing there; in your text, <code>Esc</code> just closes the panel. <strong>Done</strong> does the same with the mouse.</p><h2 id="replace" tabindex="-1">Replace <a class="header-anchor" href="#replace" aria-label="Permalink to &quot;Replace {#replace}&quot;">​</a></h2><p>Type the new text in the second field. Without a match, the arrows, <strong>Replace</strong> and <strong>Replace all</strong> are greyed out. <strong>Replace</strong>, or <code>Enter</code> in that field, changes the match you&#39;re at and moves on to the next one; <strong>Replace all</strong> changes every match in the document at once, and says how many it changed. Replace all is one step: <code>Mod</code> <code>Z</code> undoes all of it.</p><p>Find and replace looks in your text: paragraphs, headings, lists, quotes, table cells and code. It leaves the <a href="./pages#frontmatter">document properties</a> at the top of the file alone, and it doesn&#39;t search table captions or headers and footers yet.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options {#options}&quot;">​</a></h2><p>Three buttons under the find field change how it looks. Blank remembers them until you quit it.</p><ul><li><strong>Aa</strong>, match case: <em>Blank</em> finds only <em>Blank</em>, not <em>blank</em>. Without it, upper and lower case don&#39;t matter.</li><li><strong>ab|</strong>, whole word: <em>the</em> finds <em>the</em>, but not <em>theme</em> or <em>bathe</em>.</li><li><strong>.*</strong>, regular expression: the field takes a JavaScript regular expression. If Blank can&#39;t read it, the panel says why.</li></ul><p>A regular expression runs as you type, on every line: a pattern that takes long, like <code>(a+)+$</code> on a long run of a&#39;s, can hold Blank up.</p><p>With a regular expression, the replacement can use what it matched: <code>$&amp;</code> is the whole match, <code>$1</code>, <code>$2</code> … are its groups in parentheses, and <code>$&lt;name&gt;</code> a named group. For example:</p><table tabindex="0"><thead><tr><th>Find</th><th>Replace with</th><th>Turns</th><th>Into</th></tr></thead><tbody><tr><td><code>(\\w+)@(\\w+)</code></td><td><code>$1 at $2</code></td><td>ann@example</td><td>ann at example</td></tr><tr><td><code>(\\d+)-(\\d+)</code></td><td><code>$1–$2</code></td><td>pages 10-12</td><td>pages 10–12</td></tr><tr><td><code>\\s+$</code></td><td>(nothing)</td><td>spaces at a line&#39;s end</td><td>gone</td></tr></tbody></table>',13))])}const b=n(i,[["render",c]]);export{w as __pageData,b as default};
